import 'server-only';
import { getServiceClient } from '@/server/db/client';
import { HttpError } from '@/server/http/respond';

export const SME_FILES_BUCKET = 'sme-files';

/** Uploads only to the private bucket. The key is generated by the caller and never includes a user filename. */
export async function uploadPrivateFile(key: string, bytes: Uint8Array, mediaType: string): Promise<void> {
  const body = Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const { error } = await getServiceClient().storage.from(SME_FILES_BUCKET).upload(key, body, {
    contentType: mediaType,
    cacheControl: '0',
    upsert: false,
  });
  if (error) throw new HttpError('INTERNAL');
}

/** Best-effort rollback for an uploaded object whose database record failed. Never logs the object key. */
export async function removePrivateFile(key: string): Promise<void> {
  const { error } = await getServiceClient().storage.from(SME_FILES_BUCKET).remove([key]);
  if (error) console.error('[files] orphan cleanup failed', error.statusCode ?? 'unknown');
}

export async function createPrivateDownloadUrl(key: string, filename: string, expiresIn: number): Promise<string> {
  const { data, error } = await getServiceClient().storage.from(SME_FILES_BUCKET).createSignedUrl(key, expiresIn, {
    download: filename,
  });
  if (error || !data?.signedUrl) throw new HttpError('INTERNAL');
  return data.signedUrl;
}
